#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')

TEN_DAY = {'days_per_dispatch': 10, 'dispatches_per_year': 36}
TWENTY_DAY = {'days_per_dispatch': 20, 'dispatches_per_year': 18}


def money(value):
    return round(float(value), 2)


def load_catalog(path):
    with path.open() as f:
        catalog = json.load(f)

    programs = {}
    label_to_code = {}
    for group in catalog.get('service_groups', []):
        for program in group.get('programs', []):
            if program.get('review_flag') != 'review':
                continue
            code = program['program_code']
            programs[code] = program
            label_to_code[program['program_name']] = code
            for label in program.get('known_labels', []):
                label_to_code[label] = code
    return programs, label_to_code


def load_cooler_costs(path):
    with path.open(newline='') as f:
        return {
            row['cooler_type']: float(row['cooler_cost_usd'])
            for row in csv.DictReader(f)
        }


def load_payments(path, label_to_code):
    payments = {}
    with path.open(newline='') as f:
        for row in csv.DictReader(f):
            code = label_to_code.get(row['program_label'])
            if code is None:
                continue
            payments[code] = float(row['payment_per_dispatch_per_site_usd'])
    return payments


def load_site_overrides(path):
    latest_approved = {}
    with path.open(newline='') as f:
        for row in csv.DictReader(f):
            if row['approval_state'] != 'approved':
                continue
            code = row['program_code']
            version = int(row['version_no'])
            if code not in latest_approved or version > latest_approved[code]['version_no']:
                latest_approved[code] = {
                    'version_no': version,
                    'active_sites': int(row['active_sites']),
                }
    return {code: data['active_sites'] for code, data in latest_approved.items()}


def compute_model(program, active_sites, payment_per_dispatch, cooler_cost, days_per_dispatch, dispatches_per_year):
    annual_drug_cost = (
        float(program['acquisition_cost_per_1000_units_usd'])
        * active_sites
        * float(program['units_per_day'])
        * days_per_dispatch
        * dispatches_per_year
        / 1000
    )
    annual_cooler_cost = cooler_cost * active_sites * dispatches_per_year
    annual_revenue = payment_per_dispatch * active_sites * dispatches_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_cooler_cost
    return {
        'days_per_dispatch': days_per_dispatch,
        'dispatches_per_year': dispatches_per_year,
        'annual_drug_cost_usd': money(annual_drug_cost),
        'annual_cooler_cost_usd': money(annual_cooler_cost),
        'annual_revenue_usd': money(annual_revenue),
        'annual_margin_usd': money(annual_margin),
    }


def main():
    programs, label_to_code = load_catalog(ROOT / 'program_catalog.json')
    cooler_costs = load_cooler_costs(ROOT / 'cooler_cost.csv')
    payments = load_payments(ROOT / 'contract_payment.csv', label_to_code)
    site_overrides = load_site_overrides(ROOT / 'site_overrides.csv')

    output_programs = []
    total_margin_10 = 0.0
    total_margin_20 = 0.0
    total_difference = 0.0

    for code in sorted(programs):
        program = programs[code]
        active_sites = int(site_overrides.get(code, program['default_active_sites']))
        cooler_type = program['cooler_type']
        cooler_cost = float(cooler_costs[cooler_type])
        payment = float(payments.get(code, 0.0))

        model_10 = compute_model(
            program, active_sites, payment, cooler_cost,
            TEN_DAY['days_per_dispatch'], TEN_DAY['dispatches_per_year']
        )
        model_20 = compute_model(
            program, active_sites, payment, cooler_cost,
            TWENTY_DAY['days_per_dispatch'], TWENTY_DAY['dispatches_per_year']
        )
        difference = money(model_20['annual_margin_usd'] - model_10['annual_margin_usd'])

        total_margin_10 += model_10['annual_margin_usd']
        total_margin_20 += model_20['annual_margin_usd']
        total_difference += difference

        output_programs.append({
            'program_code': code,
            'program_name': program['program_name'],
            'active_sites': active_sites,
            'cooler_type': cooler_type,
            'cooler_cost_usd': money(cooler_cost),
            'payment_per_dispatch_per_site_usd': money(payment),
            'ten_day_model': model_10,
            'twenty_day_model': model_20,
            'annual_margin_difference_20_minus_10_usd': difference,
        })

    total_margin_10 = money(total_margin_10)
    total_margin_20 = money(total_margin_20)
    total_difference = money(total_difference)
    absolute_difference = money(abs(total_difference))
    decision = 'move_to_20_day' if absolute_difference < 10000 else 'keep_10_day'

    result = {
        'assumptions': {
            'catalog_filter': 'Only programs where review_flag == "review" are included.',
            'contract_matching': 'program_label must equal program_name or one of known_labels for an in-scope program.',
            'site_overrides': 'Only approved overrides are eligible; for each program_code the highest version_no is used.',
            'default_active_sites': 'Catalog default_active_sites is used when no approved override exists.',
            'cooler_cost_basis': 'Cooler cost is per site per dispatch: cooler_cost_usd * active_sites * dispatches_per_year.',
            'ten_day_model': '10 days per dispatch and 36 dispatches per year.',
            'twenty_day_model': '20 days per dispatch and 18 dispatches per year.',
            'rounding': 'Currency values are rounded to 2 decimal places.',
            'decision_rule': 'If abs(total annual margin difference) < 10000, move_to_20_day; otherwise keep_10_day.',
        },
        'programs': output_programs,
        'totals': {
            'total_annual_margin_10_day_usd': total_margin_10,
            'total_annual_margin_20_day_usd': total_margin_20,
            'total_annual_margin_difference_20_minus_10_usd': total_difference,
            'absolute_total_margin_difference_usd': absolute_difference,
        },
        'recommendation': {
            'decision': decision,
            'justification': (
                f"Absolute total annual margin difference is ${absolute_difference:,.2f}; "
                f"decision rule selects {decision}."
            ),
        },
    }

    with (ROOT / 'oncocooler_analysis.json').open('w') as f:
        json.dump(result, f, indent=2)
        f.write('\n')

    summary_lines = [
        '# OncoCooler dispatch model summary',
        f"Total 10-day margin (USD): {total_margin_10:.2f}",
        f"Total 20-day margin (USD): {total_margin_20:.2f}",
        f"Absolute difference (USD): {absolute_difference:.2f}",
        f"Decision: {decision}",
    ]
    (ROOT / 'oncocooler_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()
